if(document.modelContext?.registerTool){const controller=new AbortController();const defs=[{name:'read_game_state',title:'게임 상태 확인',description:'Read the current visible game state without changing it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>game.snapshot()},{name:'start_survival_game',title:'생존 게임 시작',description:'Start an unlocked stage. Refuses locked stages or an in-progress game.',inputSchema:{type:'object',properties:{stage:{type:'integer',minimum:1,maximum:3}},required:['stage'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Number.isInteger(input.stage)||input.stage<1||input.stage>3||Object.keys(input).length!==1)throw Error('stage must be 1, 2 or 3');if(!selectStage(input.stage-1))throw Error('Stage is locked or a game is already in progress');start();return game.snapshot();}}];for(const tool of defs){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
